from common import *
# Đề thi vào 10 chuyên Lý thật (từ các file người dùng tải về), chép lại để đọc bằng lời.
# Lời giải viết lại và đã kiểm tra; chỗ đáp án gốc in sai đã sửa.
P("D01", 3, "Lam Sơn 2012 – Hai người đưa thư",
  "Đề thi vào 10 chuyên Lam Sơn năm 2012. Giữa hai bưu điện A và B có hai người đưa thư chuyển động thẳng đều, xuất phát cùng lúc, đi về phía nhau. Khi gặp nhau họ đổi thư rồi lập tức quay về nơi xuất phát. Tốc độ người từ A khi đi bằng tốc độ người từ B khi về, bằng V1. Tốc độ người từ A khi về bằng tốc độ người từ B khi đi, bằng V2. Tổng thời gian đi và về của người từ A là 3 giờ, của người từ B là 1,5 giờ. Câu a: tìm tỉ số V1 trên V2. Câu b: giữ nguyên các tốc độ, người từ A phải xuất phát sau người từ B bao lâu để tổng thời gian đi và về của hai người bằng nhau?",
  "a) V1/V2 = 2; b) người từ A xuất phát sau 0,75 giờ (45 phút)",
  ["Gọi thời điểm gặp nhau là t0. Mỗi người đi đến chỗ gặp mất t0, rồi quay về cùng quãng đường đó với tốc độ kia.", "Lập hai phương trình: t0 cộng V1·t0/V2 bằng 3, và t0 cộng V2·t0/V1 bằng 1,5. Chia hai phương trình cho nhau."],
  "a) Đặt r = V1/V2. Người A: t0(1 + r) = 3. Người B: t0(1 + 1/r) = 1,5. Chia hai vế được r = 2, t0 = 1 h. b) Lấy V2 = 1, V1 = 2 đơn vị, AB = 3. B xuất phát lúc 0, A xuất phát lúc Δ. Gặp nhau lúc T: T + 2(T − Δ) = 3. Thời gian của B: T + T/2 = 1,5T. Thời gian của A: (T − Δ) + 2(T − Δ) = 3(T − Δ). Cho bằng nhau được Δ = T/2, thay vào được T = 1,5 h và Δ = 0,75 h.",
  "abs(1.5*1.5-3*(1.5-0.75))<1e-9 and 1.5+2*(1.5-0.75)==3")
P("D02", 2, "Lam Sơn 2012 – Múc nước đổ vào nhiệt lượng kế",
  "Đề thi vào 10 chuyên Lam Sơn năm 2012. Nhiệt lượng kế chứa 200 g nước ở 10 độ C. Mỗi lượt, người ta đổ vào 50 g nước ở 60 độ C, chờ cân bằng nhiệt, rồi múc ra 50 g nước đổ đi. Bỏ qua trao đổi nhiệt với cốc, bình và môi trường. Phải thực hiện tối thiểu bao nhiêu lượt để nước trong nhiệt lượng kế nóng hơn 30 độ C?",
  "3 lượt (nhiệt độ sau mỗi lượt: 20; 28; 34,4 độ C)",
  ["Sau mỗi lượt, trong bình luôn còn 200 g nước. Lập công thức nhiệt độ sau lượt n theo nhiệt độ trước đó.", "200·(t_n − t_(n−1)) = 50·(60 − t_n), suy ra t_n = 0,8·t_(n−1) + 12."],
  "Cân bằng nhiệt lượt n: 200(t_n − t_(n−1)) = 50(60 − t_n), nên t_n = 0,8t_(n−1) + 12. Từ 10 độ: lượt 1 được 20 độ, lượt 2 được 28 độ, lượt 3 được 34,4 độ. Vậy cần tối thiểu 3 lượt.",
  "abs(0.8*(0.8*(0.8*10+12)+12)+12-34.4)<1e-9 and 0.8*(0.8*10+12)+12<30")
P("D03", 3, "Lam Sơn 2012 – Đèn và biến trở",
  "Đề thi vào 10 chuyên Lam Sơn năm 2012. Hiệu điện thế 40 V đặt vào mạch gồm: đèn có điện trở 2,5 Ω, nối tiếp điện trở R1 bằng 2,5 Ω, nối tiếp một cụm biến trở MN có điện trở toàn phần 20 Ω với con chạy C. Trong cụm này, đoạn CM mắc song song với nhánh gồm đoạn CN nối tiếp một ampe kế lí tưởng. Câu 1: điều chỉnh C để đèn sáng bình thường thì ampe kế chỉ 2 A. Xác định vị trí con chạy và các giá trị định mức của đèn. Câu 2: tìm vị trí con chạy để công suất trên biến trở lớn nhất, tính công suất đó và nhận xét độ sáng của đèn.",
  "1) C ở chính giữa biến trở; đèn định mức 4 A, 10 V, 40 W. 2) C ở chính giữa, công suất biến trở lớn nhất 80 W, đèn sáng bình thường",
  ["Đặt điện trở đoạn CM là x, đoạn CN là 20 − x. Cụm biến trở có điện trở x(20 − x)/20.", "Ampe kế đo dòng qua đoạn CN. Với câu 2, công suất trên một phần mạch lớn nhất khi điện trở phần đó bằng điện trở phần còn lại, ở đây là 5 Ω."],
  "Đặt CM = x. R_cụm = x(20 − x)/20, R_mạch = 5 + R_cụm. Dòng qua ampe kế: I_A = 40x/(−x² + 20x + 100). Cho I_A = 2 được x² = 100, x = 10 Ω: C ở chính giữa. Khi đó dòng qua mỗi nửa là 2 A, dòng qua đèn 4 A, nên định mức 4 A, 10 V, 40 W. Câu 2: P biến trở = 1600·y/(y + 5)², lớn nhất khi y = 5 Ω, tức x(20 − x)/20 = 5, x = 10. P lớn nhất = 1600/20 = 80 W. Lúc này đèn có dòng 4 A, sáng bình thường.",
  "abs(40/(5+5)*5/10-2)<1e-9 and 40**2/(4*5)==80")
P("D04", 3, "Lam Sơn 2012 – Dịch chuyển thấu kính",
  "Đề thi vào 10 chuyên Lam Sơn năm 2012. Vật sáng AB đặt vuông góc với trục chính của thấu kính hội tụ, A trên trục chính, cho ảnh thật cao gấp 2 lần vật. Giữ nguyên vật, dịch thấu kính dọc trục chính ra xa vật 15 cm thì ảnh cũng dịch chuyển 15 cm so với vị trí ảnh ban đầu. Tính tiêu cự và khoảng cách ban đầu từ vật đến thấu kính.",
  "f = 30 cm; ban đầu vật cách thấu kính 45 cm",
  ["Ảnh thật gấp 2 lần: d' = 2d, nên f = 2d/3.", "Gọi L là khoảng cách vật ảnh. Sau khi dịch, d tăng 15 cm và L thay đổi 15 cm. Thử điều kiện L2 = L1 − 15."],
  "Ban đầu d1' = 2d1, f = 2d1/3, L1 = 3d1. Sau khi dịch: d2 = d1 + 15, d2' = d2f/(d2 − f). Ảnh dịch 15 cm trong khi thấu kính dịch ra xa 15 cm, nên L2 = L1 − 15. Giải được d1 = 45 cm, f = 30 cm. Kiểm tra: d2 = 60, d2' = 60, L2 = 120 = 135 − 15.",
  "abs(1/(1/30-1/45)-90)<1e-9 and abs(1/(1/30-1/60)-60)<1e-9 and 45+90-15==60+60")
P("D05", 2, "Hà Nội 2015 – Bình tiền vàng",
  "Đề thi vào 10 chuyên Hà Nội năm 2015. Ông lão đánh cá vớt được một chiếc bình đất nung nút kín, đang trôi lơ lửng ngập hoàn toàn trong nước. Trong bình có 400 đồng tiền vàng giống nhau. Ông lấy hết tiền ra, đậy kín bình rồi thả xuống sông thì thấy một phần ba bình nhô lên khỏi mặt nước. Bình có thể tích ngoài 4,5 lít, khối lượng riêng của nước là 1000 kg/m³. Tìm khối lượng mỗi đồng tiền.",
  "3,75 g",
  ["Lúc có tiền, bình lơ lửng: trọng lượng bình cộng tiền bằng lực đẩy khi chìm hết.", "Lúc không có tiền, bình nổi với hai phần ba thể tích chìm."],
  "Có tiền: P_bình + P_tiền = d·V = 45 N. Không tiền: P_bình = 2/3·45 = 30 N. Vậy P_tiền = 15 N, khối lượng tiền 1,5 kg. Mỗi đồng: 1500/400 = 3,75 g.",
  "1500/400==3.75")
P("D06", 3, "Hà Nội 2015 – Nước nóng chảy vào bể",
  "Đề thi vào 10 chuyên Hà Nội năm 2015. Người ta dẫn nước nóng có nhiệt độ không đổi chảy đều vào một bể có sẵn nước lạnh. Coi cân bằng nhiệt xảy ra ngay và bỏ qua trao đổi nhiệt với môi trường. Sau phút thứ nhất, nhiệt độ nước trong bể tăng 0,8 độ so với ban đầu. Sau phút thứ hai, tăng 1,2 độ so với ban đầu. Hỏi sau bao lâu nhiệt độ nước trong bể tăng 2 độ so với ban đầu?",
  "10 phút",
  ["Mỗi phút có một lượng nước nóng m chảy vào lượng nước lạnh M. Gọi a là hiệu nhiệt độ nước nóng và nước lạnh ban đầu.", "Sau n phút: n·m·(a − Δt) = M·Δt. Viết cho n = 1 và n = 2 để tìm a và tỉ số M/m."],
  "Đặt k = M/m. Phút 1: a − 0,8 = 0,8k. Phút 2: 2(a − 1,2) = 1,2k. Giải ra k = 2, a = 2,4 độ. Với Δt = 2: n(2,4 − 2) = 2·2, nên n = 10 phút.",
  "abs((2.4-0.8)-0.8*2)<1e-9 and abs(2*(2.4-1.2)-1.2*2)<1e-9 and abs(2*2/(2.4-2)-10)<1e-9")
P("D07", 2, "Hà Nội 2015 – Các chế độ bàn là",
  "Đề thi vào 10 chuyên Hà Nội năm 2015. Một bàn là dùng ở hiệu điện thế 220 V có hai dây điện trở 96,8 Ω và 48,4 Ω. Bằng cách nối các chốt, có thể cho dòng điện chạy qua: hai dây nối tiếp, chỉ dây 96,8 Ω, chỉ dây 48,4 Ω, hoặc hai dây song song. Tính công suất của từng chế độ.",
  "Nối tiếp khoảng 333 W; dây 96,8 Ω: 500 W; dây 48,4 Ω: 1000 W; song song: 1500 W",
  ["P = U²/R với R của từng cách mắc.", "Song song thì công suất bằng tổng công suất hai dây."],
  "Nối tiếp: 220²/145,2 ≈ 333 W. Dây 96,8 Ω: 220²/96,8 = 500 W. Dây 48,4 Ω: 220²/48,4 = 1000 W. Song song: 500 + 1000 = 1500 W. Vậy bàn là có 4 chế độ.",
  "abs(220**2/145.2-333.3)<0.1 and abs(220**2/96.8-500)<1e-6 and abs(220**2/48.4-1000)<1e-6")
P("D08", 1, "Hà Nội 2015 – Giảm hao phí truyền tải",
  "Đề thi vào 10 chuyên Hà Nội năm 2015. Để giảm hao phí khi truyền tải điện đi xa, người ta có thể dùng những cách nào? Nêu nhược điểm của mỗi cách.",
  "Giảm điện trở suất, tăng tiết diện dây, tăng hiệu điện thế truyền tải",
  ["Công suất hao phí bằng P²·ρ·l/(U²·S)."],
  "Hao phí P_hp = P²ρl/(U²S). Cách 1: dùng dây có điện trở suất nhỏ, nhưng kim loại đó đắt. Cách 2: tăng tiết diện dây, nhưng dây nặng, tốn vật liệu, cột phải chắc hơn. Cách 3: tăng hiệu điện thế bằng máy biến áp, hiệu quả nhất vì hao phí giảm theo U², nhưng cần máy biến áp và đường dây cao thế nguy hiểm.")
P("D09", 3, "Hà Nội 2015 – Máy phát điện và số đèn",
  "Đề thi vào 10 chuyên Hà Nội năm 2015. Một máy phát điện công suất không đổi cấp điện cho các bóng đèn giống nhau qua đường dây có điện trở đáng kể, có dùng máy biến áp lí tưởng ở hai đầu. Nếu tăng hiệu điện thế nơi phát từ 220 V lên 440 V thì số đèn sáng bình thường tăng từ 9 lên 36. Câu a: tính số đèn khi hiệu điện thế nơi phát là 660 V. Câu b: tăng hiệu điện thế đến bao nhiêu thì số đèn đạt lớn nhất, và số đèn lớn nhất là bao nhiêu?",
  "a) 41 đèn; b) 1320 V, tối đa 44 đèn",
  ["Gọi công suất mỗi đèn là x, hao phí ở 220 V là ΔP. Hao phí tỉ lệ nghịch với U².", "P = 9x + ΔP và P = 36x + ΔP/4."],
  "Từ hai phương trình: ΔP = 36x, P = 45x. Ở 660 V hao phí bằng ΔP/9 = 4x, nên số đèn là 41. Số đèn phải là số nguyên và hao phí luôn lớn hơn 0, nên tối đa 44 đèn, khi hao phí bằng x = ΔP/36, tức U tăng 6 lần: 1320 V.",
  "45-36/9==41 and 220*6==1320")
P("D10", 3, "KHTN Hà Nội 2014 – Mẩu hợp kim trong hai bình",
  "Đề thi vào 10 chuyên Khoa học Tự nhiên Hà Nội năm 2014. Hai bình nhiệt lượng kế giống nhau chứa cùng một lượng chất lỏng X ở cùng nhiệt độ. Bình 1: đổ thêm nước cùng nhiệt độ với X, rồi thả một mẩu hợp kim thì bình vừa đầy. Khi cân bằng, nhiệt độ chất lỏng tăng 4 độ, mẩu hợp kim giảm 70 độ. Bình 2: thả 7 mẩu hợp kim giống hệt thì bình cũng vừa đầy, và khi cân bằng, độ tăng nhiệt độ của X bằng độ giảm nhiệt độ của các mẩu hợp kim. Nhiệt dung riêng của nước 4200, khối lượng riêng nước 1 g/cm³, của hợp kim 3 g/cm³. Hợp kim nặng hơn X, X nặng hơn nước; các chất lỏng không trộn lẫn. Tìm nhiệt dung riêng của hợp kim.",
  "800 J/kg.K",
  ["Hai bình cùng đầy nên thể tích nước ở bình 1 bằng thể tích của 6 mẩu hợp kim.", "Bình 2: q_X·Δt = 7mc·Δt nên q_X = 7mc. Bình 1: (q_X + m_nước·c_nước)·4 = mc·70."],
  "Thể tích nước bằng 6 mẩu: m_nước = 6m·D_nước/D = 2m. Bình 2 cho q_X = 7mc. Bình 1: (7mc + 2m·4200)·4 = 70mc, nên 28c + 33 600 = 70c, c = 800 J/kg.K.",
  "abs(6*1*4200*4/(3*(70-28))-800)<1e-9")
P("D11", 3, "KHTN Hà Nội 2014 – Bình thông nhau có vật nổi và dầu",
  "Đề thi vào 10 chuyên KHTN Hà Nội năm 2014. Bình thông nhau có hai nhánh hình trụ, tiết diện 100 cm² và 60 cm², chứa nước, mực nước cách miệng 3 cm. Câu 1: thả vào nhánh lớn một vật nặng 80 g, khối lượng riêng 0,8 g/cm³. Mực nước nhánh nhỏ dâng thêm bao nhiêu? Câu 2: sau đó đổ dầu khối lượng riêng 0,75 g/cm³ vào nhánh lớn đến đầy, vật ngập hoàn toàn trong nước và dầu. Tính thể tích phần vật ngập trong nước và khối lượng dầu đã đổ.",
  "1) 0,5 cm; 2) 20 cm³ trong nước, đổ 240 g dầu",
  ["Câu 1: vật nổi chiếm chỗ 80 cm³ nước, chia cho tổng diện tích hai nhánh.", "Câu 2: vật thể tích 100 cm³, cân bằng: 1·V_nước + 0,75·(100 − V_nước) = 80. Sau đó dùng cân bằng áp suất ở mặt phân cách và bảo toàn thể tích nước."],
  "1) Mực nước dâng 80/160 = 0,5 cm. 2) V_n + 0,75(100 − V_n) = 80, nên V_n = 20 cm³, phần trong dầu 80 cm³. Gọi h là độ dâng nước nhánh nhỏ, x là độ hạ mặt phân cách nhánh lớn (so với mực ban đầu): 60h = 100x + 20 và (h + x)·1 = (3 + x)·0,75. Giải được x = 1 cm, h = 2 cm. Thể tích dầu: 100·(3 + 1) − 80 = 320 cm³, khối lượng 240 g.",
  "abs(80/160-0.5)<1e-9 and 60*2==100*1+20 and abs((2+1)-(3+1)*0.75)<1e-9 and (400-80)*0.75==240")
P("D12", 3, "KHTN Hà Nội 2014 – Vật đặt dọc trục chính",
  "Đề thi vào 10 chuyên KHTN Hà Nội năm 2014. Một nguồn sáng dạng đoạn thẳng AB dài 15 cm đặt dọc trục chính của thấu kính hội tụ tiêu cự 30 cm, đầu B gần thấu kính hơn, cho ảnh thật A'B' dài 30 cm. Câu 1: tính khoảng cách từ B đến thấu kính. Câu 2: đặt màn vuông góc trục chính sau thấu kính. Màn cách thấu kính bao nhiêu thì vết sáng trên màn nhỏ nhất?",
  "1) B cách thấu kính 45 cm (A cách 60 cm, ảnh B' ở 90 cm, ảnh A' ở 60 cm); 2) màn cách thấu kính 72 cm",
  ["Áp dụng công thức thấu kính cho từng đầu. Đầu A xa hơn nên ảnh A' gần thấu kính hơn: d'_A = d'_B − 30.", "Câu 2: chùm sáng từ A hội tụ tại A' rồi loe ra, chùm từ B hội tụ tại B'. Vết sáng nhỏ nhất ở chỗ hai chùm có cùng bề rộng."],
  "Đặt d_B = x: d'_B = 30x/(x − 30), d_A = x + 15, d'_A = 30(x + 15)/(x − 15). Cho d'_B − d'_A = 30 được x = 45 cm, d'_B = 90, d_A = d'_A = 60. Câu 2: với màn ở L, bề rộng chùm từ A tỉ lệ với (L − 60)/60, chùm từ B tỉ lệ với (90 − L)/90. Cho bằng nhau: L = 2·60·90/150 = 72 cm.",
  "abs(1/(1/30-1/45)-90)<1e-9 and abs(1/(1/30-1/60)-60)<1e-9 and 2*60*90/150==72")
P("D13", 3, "KHTN Hà Nội 2014 – Mạch cầu có khóa K",
  "Đề thi vào 10 chuyên KHTN Hà Nội năm 2014. Mạch giữa A và B có hiệu điện thế 43 V: R1 bằng 10 Ω nối A với M, R2 bằng 20 Ω nối M với B, R3 bằng 20 Ω nối A với N, R4 nối N với B qua khóa K. Giữa M và N mắc một ampe kế lí tưởng nối tiếp biến trở Rx. Câu 1: K mở, Rx bằng 2 Ω, ampe kế chỉ bao nhiêu? Khi Rx tăng thì số chỉ tăng hay giảm? Câu 2: K đóng, Rx bằng 10 Ω thì ampe kế chỉ 0,1 A, chiều từ M đến N. Tính R4 và chứng tỏ tỉ số công suất trên R1 và R4 không phụ thuộc Rx.",
  "1) 0,5 A, Rx tăng thì số chỉ giảm; 2) R4 = 30 Ω, tỉ số P1/P4 = 25/27",
  ["K mở: R4 không có dòng, mạch là (R1 song song (Rx + R3)) nối tiếp R2.", "K đóng: viết U = I1·R1 + I2·R2 với I2 = I1 − I_A, và U = I3·R3 + I4·R4 với I4 = I3 + I_A."],
  "1) I_A = 430/(800 + 30Rx); Rx = 2 thì I_A = 0,5 A, Rx tăng thì I_A giảm. 2) 10I1 + 20(I1 − 0,1) = 43, nên I1 = 1,5 A. U_AN = 10·1,5 + 0,1·10 = 16 V, I3 = 0,8 A, I4 = 0,9 A, U4 = 27 V, R4 = 30 Ω. Tổng quát: I1 = (U + 20I_A)/30 và I4 = (U + 20I_A)/50, tỉ số I1/I4 = 5/3 không đổi, nên P1/P4 = (25/9)·10/30 = 25/27.",
  "abs(430/(800+60)-0.5)<1e-9 and abs(27/0.9-30)<1e-9 and abs((5/3)**2*10/30-25/27)<1e-9")
P("D14", 3, "ĐHSP Hà Nội 2013 – Đường đi nhanh nhất (phỏng theo)",
  "Phỏng theo đề vào 10 chuyên Đại học Sư phạm Hà Nội năm 2013. Một người đứng ở điểm A trên bờ hồ thẳng, muốn tới điểm B trên mặt hồ. B cách bờ 40 m, hình chiếu C của B lên bờ cách A 100 m. Người đó chạy dọc bờ với tốc độ 5 m/s và bơi với tốc độ 3 m/s. Hỏi người đó nên chạy đến điểm D cách C bao xa rồi bơi thẳng tới B để mất ít thời gian nhất? Tổng quãng đường và thời gian là bao nhiêu?",
  "D cách C 30 m: chạy 70 m, bơi 50 m, tổng 120 m, mất khoảng 30,7 giây",
  ["Gọi DC = x. Thời gian t = (100 − x)/5 + √(40² + x²)/3.", "Thời gian nhỏ nhất khi x = d·v1/√(v2² − v1²), với v1 là tốc độ bơi, v2 là tốc độ chạy."],
  "t(x) = (100 − x)/5 + √(1600 + x²)/3. Biến đổi thành phương trình bậc hai theo x và cho Δ ≥ 0, được t nhỏ nhất khi x = 40·3/√(25 − 9) = 30 m. Chạy 70 m mất 14 s, bơi √(1600 + 900) = 50 m mất 16,7 s. Tổng 120 m, khoảng 30,7 s. Công thức tổng quát của đề gốc: quãng đường S + d·√((v2 − v1)/(v2 + v1)).",
  "abs(40*3/4-30)<1e-9 and abs(70/5+50/3-30.667)<0.001 and abs(100+40*sqrt(2/8)-120)<1e-9")
P("D15", 3, "ĐHSP Hà Nội 2013 – Nhúng nhiệt kế qua lại",
  "Đề thi vào 10 chuyên ĐHSP Hà Nội năm 2013. Có hai nhiệt lượng kế chứa hai chất lỏng khác nhau ở nhiệt độ khác nhau. Lần lượt nhúng một nhiệt kế vào bình 1, rồi bình 2, rồi bình 1, rồi bình 2, mỗi lần chờ cân bằng mới rút ra. Số chỉ nhiệt kế các lần là 80; 16; 78; 19 độ C. Bỏ qua mất mát nhiệt. Câu 1: lần thứ 5 nhiệt kế chỉ bao nhiêu? Câu 2: sau rất nhiều lần nhúng, nhiệt kế chỉ bao nhiêu?",
  "1) Khoảng 76,2 độ C; 2) khoảng 54,4 độ C",
  ["Gọi nhiệt dung của bình 1, bình 2, nhiệt kế là q1, q2, q. Lần 3 cho q1 theo q; lần 4 cho q2 theo q.", "Sau rất nhiều lần, cả hệ cùng một nhiệt độ: dùng bảo toàn năng lượng kể từ sau lần 2."],
  "Lần 3: q1(80 − 78) = q(78 − 16), nên q1 = 31q. Lần 4: q2(19 − 16) = q(78 − 19), nên q2 = 59q/3. Lần 5: 31q(78 − t) = q(t − 19), t ≈ 76,2 độ C. Cuối cùng: 31·80 + (59/3)·16 + 1·16 = (31 + 59/3 + 1)·T, nên T ≈ 54,4 độ C. Đáp án gốc ghi 54,5 là do làm tròn.",
  "abs((31*78+19)/32-76.16)<0.01 and abs((31*80+59/3*16+16)/(31+59/3+1)-54.4)<0.01")
P("D16", 3, "ĐHSP Hà Nội 2013 – Mạch nhiều điện trở có biến trở",
  "Đề thi vào 10 chuyên ĐHSP Hà Nội năm 2013. Hiệu điện thế 18 V đặt vào mạch: điện trở r bằng 4 Ω nối tiếp với một cụm song song gồm hai nhánh. Nhánh thứ nhất: R2 bằng 4 Ω nối tiếp với cụm (R1 bằng 12 Ω song song với biến trở R3 nối tiếp đèn có điện trở 3 Ω). Nhánh thứ hai: R4 bằng 18 Ω nối tiếp R5 bằng 6 Ω. Câu 1: với R3 bằng 21 Ω, tính dòng điện qua R3, qua R5 và công suất của đèn. Câu 2: R3 thay đổi từ 0 đến 30 Ω. Tìm R3 để công suất trên R3 lớn nhất và tính giá trị đó.",
  "1) I3 = 1/3 A, I5 = 0,5 A, đèn 1/3 W; 2) R3 ≈ 7,6 Ω, công suất lớn nhất khoảng 3 W",
  ["Câu 1: tính lần lượt R3 + đèn = 24 Ω, song song R1 được 8 Ω, cộng R2 được 12 Ω, song song 24 Ω được 8 Ω, cộng r được 12 Ω.", "Câu 2: biểu diễn I3 = 162/(17x + 129) với x = R3, rồi dùng Cô-si cho P3 = I3²·x."],
  "1) R mạch 12 Ω, I = 1,5 A, U cụm song song 12 V. I5 = 12/24 = 0,5 A. Nhánh thứ nhất có dòng 1 A, U trên cụm R1 là 8 V, I3 = 8/24 = 1/3 A, P_đèn = (1/3)²·3 = 1/3 W. 2) Biến đổi được I3 = 162/(17x + 129). P3 = 162²·x/(17x + 129)² lớn nhất khi 17x = 129, tức x = 129/17 ≈ 7,6 Ω, P lớn nhất = 162²/(4·17·129) ≈ 3 W.",
  "abs(162**2/(4*17*129)-2.99)<0.01 and abs(129/17-7.59)<0.01")
P("D17", 3, "ĐHSP Hà Nội 2013 – Dây dẫn nóng lên",
  "Đề thi vào 10 chuyên ĐHSP Hà Nội năm 2013. Một dây dẫn có điện trở không đổi. Dòng 2 A chạy qua thì dây nóng đến nhiệt độ ổn định 50 độ C, dòng 4 A thì 150 độ C. Khi nhiệt độ ổn định, nhiệt tỏa ra môi trường tỉ lệ với độ chênh lệch nhiệt độ giữa dây và môi trường. Câu 1: gọi a và b là thời gian để dây đạt nhiệt độ ổn định với dòng 2 A và 4 A, coi trong lúc nóng lên nhiệt tỏa ra môi trường không đáng kể. Chứng minh a bằng b. Câu 2: với dòng 6 A thì dây nóng đến bao nhiêu độ?",
  "1) a = b; 2) khoảng 317 độ C",
  ["Lúc ổn định: I²R = k(t − t0). Dùng hai dòng điện để tìm nhiệt độ môi trường t0.", "Lúc nóng lên: I²R·thời gian = mc(t − t0)."],
  "4/16 = (50 − t0)/(150 − t0), nên t0 = 50/3 độ C. Câu 1: 4a/(16b) = (50 − t0)/(150 − t0) = 1/4, nên a = b. Câu 2: 4/36 = (50 − t0)/(t3 − t0), nên t3 − 50/3 = 300, t3 ≈ 317 độ C.",
  "abs((50-50/3)/(150-50/3)-0.25)<1e-9 and abs(9*(50-50/3)+50/3-316.67)<0.01")
P("D18", 3, "ĐHSP Hà Nội 2013 – Hệ hai thấu kính và màn",
  "Đề thi vào 10 chuyên ĐHSP Hà Nội năm 2013. Vật AB đặt trước thấu kính O1, cách O1 12 cm. Sau O1 là thấu kính hội tụ O2 tiêu cự 9 cm, sau nữa là màn cách O1 60 cm. Giữ vật, O1 và màn cố định, dịch O2 trong khoảng giữa O1 và màn thì thấy có hai vị trí của O2 cho ảnh rõ nét trên màn, hai vị trí cách nhau 24 cm. Câu 1: tính tiêu cự O1. Câu 2: tịnh tiến vật dọc trục chính trước O1. Hai thấu kính phải cách nhau bao nhiêu để ảnh cuối cùng có độ cao không phụ thuộc vị trí vật?",
  "1) f1 = 6 cm; 2) hai thấu kính cách nhau 15 cm (bằng f1 + f2)",
  ["Ảnh của vật qua O1 là vật của O2, đứng yên. Hai vị trí của O2 đối xứng: d2 và d2' đổi chỗ cho nhau, và d2' − d2 = 24.", "Câu 2: tia tới song song trục chính từ đỉnh vật phải ló ra song song: tiêu điểm sau của O1 trùng tiêu điểm trước của O2."],
  "Hai vị trí của O2: d2 + d2' không đổi và d2' − d2 = 24. Với f2 = 9: d2 = 12, d2' = 36. Ảnh qua O1 cách O1: 60 − 48 = 12 cm, nên f1 = 12·12/24 = 6 cm. Câu 2: O1O2 = f1 + f2 = 15 cm. Đáp án gốc ghi 12 cm là cộng nhầm.",
  "abs(1/(1/9-1/12)-36)<1e-9 and abs(1/(1/9-1/36)-12)<1e-9 and 12*12/24==6 and 6+9==15")
P("D19", 3, "Bắc Giang 2015 – Ca nô và dòng nước",
  "Đề thi vào 10 chuyên Bắc Giang năm 2015. Một ca nô đi trên quãng sông AB. Những hôm nước chảy, thời gian xuôi dòng từ A đến B ít hơn thời gian những hôm nước yên lặng là 9 phút, còn thời gian ngược dòng từ B về A là 1 giờ 24 phút. Coi tốc độ dòng nước không đổi và công suất ca nô ổn định. Tính thời gian ca nô đi từ A đến B những hôm nước yên lặng.",
  "Hai nghiệm đều hợp lệ: 1 giờ 12 phút hoặc 21 phút",
  ["Gọi S, v, u. Lập hai phương trình: S/v − S/(v + u) = 0,15 giờ, và S/(v − u) = 1,4 giờ.", "Chia hai phương trình để được phương trình bậc hai theo tỉ số v/u."],
  "Chia hai phương trình được 3x² − 25x + 28 = 0 với x = v/u, nên x = 7 hoặc x = 4/3. Với x = 7: S/v = 1,2 h = 1 giờ 12 phút. Với x = 4/3: S/v = 0,35 h = 21 phút. Cả hai đều thỏa mãn.",
  "abs(1.2-1.2/(1+1/7)-0.15)<1e-9 and abs(1.2/(1-1/7)-1.4)<1e-9 and abs(0.35-0.35/(1+3/4)-0.15)<1e-9 and abs(0.35/(1-3/4)-1.4)<1e-9")
P("D20", 3, "Bắc Giang 2015 – Thanh tựa tường",
  "Đề thi vào 10 chuyên Bắc Giang năm 2015. Thanh AB dài L, trọng lượng P, trọng tâm G cách đầu A là 0,6L. Đầu A tựa vào tường thẳng đứng, trung điểm M của thanh buộc dây MC vào điểm C trên tường, phía trên A, với CA = L. Khi cân bằng, thanh hợp với tường góc 60 độ. Tính lực căng dây, phản lực của tường, lực ma sát, và hệ số ma sát tối thiểu.",
  "T ≈ 1,04P (3√3P/5); N ≈ 0,52P; lực ma sát 0,1P; hệ số ma sát k ≥ 0,19",
  ["Tam giác ACB có CA = AB = L và góc A bằng 60 độ nên đều, do đó dây CM vuông góc với thanh.", "Lấy mô men đối với A để tìm lực căng, rồi chiếu các lực lên phương ngang và phương thẳng đứng."],
  "Mô men đối với A: P·0,6L·sin 60 = T·L/2, nên T = 0,6√3·P ≈ 1,04P. Dây vuông góc với thanh nên hợp với phương ngang góc 60 độ. Phương ngang: N = T·cos 60 ≈ 0,52P. Phương thẳng đứng: F_ms = P − T·sin 60 = P − 0,9P = 0,1P. Cần F_ms ≤ kN, nên k ≥ 0,1/0,52 ≈ 0,19.",
  "abs(0.6*sqrt(3)-1.039)<0.001 and abs(0.6*sqrt(3)*sin(radians(60))-0.9)<1e-9 and abs(0.1/(0.3*sqrt(3))-0.192)<0.001")
P("D21", 3, "Bắc Giang 2015 – Đổ nước qua lại hai bình",
  "Đề thi vào 10 chuyên Bắc Giang năm 2015. Mỗi bình chứa 300 g nước, bình 1 ở 55,6 độ C, bình 2 ở 30 độ C. Bỏ qua mất nhiệt. Câu 1: lấy 100 g từ bình 1 đổ sang bình 2. Tính nhiệt độ bình 2. Câu 2: lấy 100 g từ bình 2 đổ lại bình 1. Tính nhiệt độ bình 1 và hiệu nhiệt độ hai bình. Câu 3: cứ đổ qua lại như vậy. Sau bao nhiêu lần đổ từ bình 2 sang bình 1 thì hiệu nhiệt độ hai bình là 0,4 độ C?",
  "1) 36,4 độ C; 2) 49,2 độ C, hiệu 12,8 độ; 3) sau 6 lần đổ từ bình 2 sang bình 1",
  ["Câu 1: (300·30 + 100·55,6)/400.", "Câu 3: chứng minh sau mỗi vòng đổ đi đổ lại, hiệu nhiệt độ giảm một nửa."],
  "1) t1 = (9000 + 5560)/400 = 36,4 độ C. 2) t2 = (200·55,6 + 100·36,4)/300 = 49,2 độ C, hiệu 12,8 độ. 3) Với k = 100/300, mỗi vòng hiệu nhiệt độ nhân với (1 − k)/(1 + k) = 1/2. Ban đầu hiệu 25,6 độ, sau n vòng còn 25,6/2ⁿ = 0,4, nên 2ⁿ = 64 và n = 6.",
  "abs((9000+5560)/400-36.4)<1e-9 and abs((200*55.6+100*36.4)/300-49.2)<1e-9 and 25.6/2**6==0.4")
P("D22", 3, "Bắc Giang 2015 – Đèn, biến trở và khóa K",
  "Đề thi vào 10 chuyên Bắc Giang năm 2015. Nguồn 18 V, đèn 12 V – 12 W, R1 bằng 3 Ω, R2 bằng 9 Ω, biến trở Rx. Khi khóa K mở, mạch là: cụm (R1 nối tiếp R2) song song với đèn, cả cụm nối tiếp Rx. Khi K đóng, mạch là: đèn nối tiếp cụm (R2 song song Rx), cả nhánh này song song với R1; ampe kế đo tổng dòng qua R1 và R2. Câu 1: tìm Rx để đèn sáng bình thường khi K mở, và khi K đóng; khi K đóng ampe kế chỉ bao nhiêu? Câu 2: K đóng, Rx bằng 3 Ω, thay đèn bằng đèn khác có I = (20/27)·U² (I tính bằng ampe, U tính bằng vôn). Tìm hiệu điện thế trên đèn.",
  "1) K mở: Rx = 3 Ω; K đóng: Rx = 18 Ω, ampe kế chỉ 20/3 A (khoảng 6,67 A); 2) U đèn = 3 V",
  ["Đèn sáng bình thường: 12 V, 1 A.", "Câu 2: U_đèn + I_đèn·(R2 song song Rx) = 18, với R2 song song Rx = 2,25 Ω."],
  "1) K mở: cụm R1 + R2 = 12 Ω nhận 12 V nên có 1 A, Rx nhận 6 V và 2 A, Rx = 3 Ω. K đóng: cụm R2 song song Rx nhận 6 V, I2 = 2/3 A, Ix = 1/3 A, Rx = 18 Ω. I1 = 18/3 = 6 A, ampe kế chỉ 6 + 2/3 = 20/3 A. 2) U + (20/27)U²·2,25 = 18, tức 5U² + 3U − 54 = 0, U = 3 V.",
  "abs(5*9+3*3-54)<1e-9 and abs(6/(1-2/3)-18)<1e-9")
P("D23", 3, "Bắc Giang 2015 – Điểm sáng trên trục chính",
  "Đề thi vào 10 chuyên Bắc Giang năm 2015. Điểm sáng S trên trục chính của thấu kính hội tụ tiêu cự f, cách tiêu điểm gần nó 1,5f, cho ảnh thật S' cách tiêu điểm gần S' một khoảng 40/3 cm. Câu 1: tìm f và vị trí ban đầu của S. Câu 2: S cách thấu kính d (ngoài tiêu cự), chuyển động theo phương hợp với trục chính 60 độ, tiến lại gần thấu kính, thì ảnh thật chuyển động theo phương hợp với trục chính 30 độ. Tính d. Câu 3: đặt thấu kính giữa hai điểm sáng A và B trên trục chính cách nhau 72 cm sao cho ảnh của A và B trùng nhau. Giữ A, B cố định, tịnh tiến thấu kính vuông góc với trục chính với tốc độ 4 cm/s. Tính tốc độ của ảnh A' so với ảnh B'.",
  "1) f = 20 cm, S cách thấu kính 50 cm; 2) d = 80/3 cm (khoảng 26,7 cm); 3) 12 cm/s",
  ["Câu 1: d = 2,5f, d' = f + 40/3.", "Câu 2: S và ảnh cùng nằm trên một tia đi qua một điểm I trên thấu kính: d·tan 60 = d'·tan 30, nên d' = 3d."],
  "1) d = 2,5f, d' = 5f/3 = f + 40/3, nên f = 20 cm, d = 50 cm. 2) d' = 3d, 1/20 = 1/d + 1/(3d), d = 80/3 cm. 3) A cho ảnh thật, B cho ảnh ảo: d_A = 60 cm, d_B = 12 cm, cả hai ảnh ở cách thấu kính 30 cm. Khi thấu kính dịch ngang v = 4 cm/s, ảnh A' đi được 4(1 + 30/60) = 6 cm/s, ảnh B' đi 4(30/12 − 1) = 6 cm/s theo chiều ngược lại. Tốc độ tương đối 12 cm/s.",
  "abs(2.5*20*20/(1.5*20)-(20+40/3))<1e-9 and abs(1/(80/3)+1/80-1/20)<1e-12 and abs(1/(1/20-1/60)-30)<1e-9 and abs(1/(1/12-1/20)-30)<1e-9")
P("D24", 3, "Bắc Giang 2015 – Đo điện trở suất của ruột bút chì",
  "Đề thi vào 10 chuyên Bắc Giang năm 2015. Cho một thanh than chì AB như ruột bút chì, một ampe kế, một vôn kế, nguồn điện một chiều, một điện trở R0, thước có độ chia 1 mm, cuộn chỉ mảnh, dây nối, khóa K. Hãy đề xuất phương án đo điện trở suất của thanh than chì.",
  "ρ = U·L²/(4·I·N²·l), với L là chiều dài N vòng chỉ quấn quanh thanh, l là đoạn thanh đo điện trở",
  ["Cần đo hai thứ: điện trở của một đoạn thanh (bằng vôn kế và ampe kế), và đường kính thanh (bằng cách quấn chỉ).", "Đường kính d = L/(πN) khi quấn N vòng chỉ sát nhau có tổng chiều dài L."],
  "Quấn N vòng chỉ sát nhau quanh thanh, gỡ ra đo chiều dài L, được d = L/(πN). Mắc nguồn, R0 (để bảo vệ), khóa K, ampe kế nối tiếp với một đoạn thanh dài l; vôn kế mắc vào hai đầu đoạn đó. Đọc U và I, R = U/I. Từ R = ρ·l/S với S = πd²/4, được ρ = U·L²/(4·I·N²·l). Đo với ít nhất ba giá trị l rồi lấy trung bình.")
P("D25", 3, "Hải Dương 2016 – Đòn bẩy và vật chìm",
  "Đề thi vào 10 chuyên Nguyễn Trãi Hải Dương năm 2016. Thanh cứng AC dài 20 cm nằm ngang, đầu C gắn vào bản lề cố định. Đầu A được kéo lên bởi một sợi dây vắt qua ròng rọc cố định, đầu kia treo vật 2. Tại điểm B trên thanh treo vật 1 là khối lập phương cạnh 10 cm, trọng lượng riêng 12 500 N/m³, chìm hoàn toàn trong nước có trọng lượng riêng 10 000 N/m³. Câu 1: bỏ qua khối lượng thanh, khi AB bằng 15 cm thì hệ cân bằng. Tìm khối lượng vật 2. Câu 2: nếu thanh có khối lượng 75 g thì AB phải bằng bao nhiêu để hệ vẫn cân bằng?",
  "1) 62,5 g; 2) AB = 18 cm",
  ["Lực kéo của vật 1 lên thanh bằng trọng lượng trừ lực đẩy Ác-si-mét: (12 500 − 10 000)·0,001 = 2,5 N.", "Lấy mô men đối với C. Lực kéo ở A bằng trọng lượng vật 2, cánh tay đòn 20 cm."],
  "1) T = 2,5 N, CB = 5 cm. 2,5·5 = P2·20, nên P2 = 0,625 N, m2 = 62,5 g. 2) Trọng lượng thanh 0,75 N đặt ở giữa, cách C 10 cm: 0,75·10 + 2,5·CB = 0,625·20, nên CB = 2 cm, AB = 18 cm.",
  "abs(2.5*5/20-0.625)<1e-9 and abs((0.625*20-0.75*10)/2.5-2)<1e-9")
P("D26", 3, "Hải Dương 2016 – Bảng số liệu đổ ca",
  "Đề thi vào 10 chuyên Nguyễn Trãi Hải Dương năm 2016. Hai bình đựng cùng một loại chất lỏng. Một học sinh múc từng ca chất lỏng từ bình 2 đổ vào bình 1 và đo nhiệt độ cân bằng của bình 1 sau mỗi lần: lần 1 là 20 độ, lần 2 là 35 độ, lần 3 là t, lần 4 là 50 độ C. Các ca có nhiệt độ và khối lượng như nhau. Bỏ qua trao đổi nhiệt với môi trường và bình. Tính t và nhiệt độ của mỗi ca.",
  "t = 44 độ C; mỗi ca có nhiệt độ 80 độ C",
  ["Gọi nhiệt dung bình 1 trước lần đổ 1 là q1, mỗi ca là q2, nhiệt độ ca là T. Lần 2: q2(T − 35) = (q1 + q2)·15.", "Viết thêm phương trình cho lần 3 và lần 4, khử q1/q2."],
  "Lần 2 cho q2(T − 50) = 15q1. Lần 3: q2(T − t) = (q1 + 2q2)(t − 35). Lần 4: q2(T − 50) = (q1 + 3q2)(50 − t). Giải ra T = 80 độ C, q1 = 2q2 và t = 44 độ C. Kiểm tra lần 4: 30 = 5·6.",
  "80-44==4*(44-35) and 80-50==5*(50-44) and 80-35==3*15")
P("D27", 3, "Hải Dương 2016 – Hai nhánh điện trở",
  "Đề thi vào 10 chuyên Nguyễn Trãi Hải Dương năm 2016. Hiệu điện thế 6 V đặt vào hai nhánh song song: nhánh trên R1 bằng 1 Ω nối tiếp R2 bằng 2 Ω, điểm giữa là C; nhánh dưới biến trở R3 nối tiếp biến trở R4, điểm giữa là D. Câu 1: R3 bằng 2,5 Ω, R4 bằng 3,5 Ω, mắc vôn kế lí tưởng giữa C và D. Vôn kế chỉ bao nhiêu? Câu 2: R3 bằng 2,5 Ω, mắc ampe kế lí tưởng giữa C và D. Tìm R4 để ampe kế chỉ 0,75 A theo chiều từ C đến D. Câu 3: R3 bằng R0 không đổi, thay đổi R4, khi R4 bằng R5 hoặc R6 thì công suất trên R4 như nhau và bằng P; khi R4 bằng R7 thì công suất lớn nhất, bằng 25P/24. Biết R5 + R6 = 6,5 Ω và R5 > R6. Tìm R0, R5, R6, R7.",
  "1) 0,5 V; 2) R4 = 2 Ω; 3) R0 = R7 = 3 Ω, R5 = 4,5 Ω, R6 = 2 Ω",
  ["Câu 2: ampe kế chập C với D, mạch thành (R1 song song R3) nối tiếp (R2 song song R4). Dòng qua ampe kế bằng I1 − I2.", "Câu 3: công suất trên R4 lớn nhất khi R4 = R0. Hai giá trị cho cùng công suất thỏa mãn R5·R6 = R0²."],
  "1) Mỗi nhánh có dòng 2 A và 1 A. U1 = 2 V, U3 = 2,5 V, vôn kế chỉ 0,5 V. 2) I1 − I2 = [30(2 + R4) − 42R4]/(10 + 19R4) = 0,75, nên R4 = 2 Ω. 3) P = U²x/(R0 + x)², lớn nhất bằng U²/(4R0) khi x = R0. Hai nghiệm cùng P có tích R0² và P = U²/(x1 + x2 + 2R0). Từ 25/24: R0 = 3 Ω, R5·R6 = 9, R5 + R6 = 6,5, nên R5 = 4,5 Ω, R6 = 2 Ω, R7 = 3 Ω.",
  "abs((30*4-42*2)/(10+38)-0.75)<1e-9 and abs(36*2/25-36*4.5/7.5**2)<1e-9 and abs(36/12/(36*2/25)-25/24)<1e-9")
P("D28", 3, "Hải Dương 2016 – Đèn và biến trở có điện trở r",
  "Đề thi vào 10 chuyên Nguyễn Trãi Hải Dương năm 2016. Hiệu điện thế 36 V đặt vào mạch: đoạn MC của biến trở mắc song song với nhánh (đèn 6 V – 6 W nối tiếp ampe kế lí tưởng); cụm này nối tiếp đoạn CN của biến trở rồi nối tiếp điện trở r bằng 1 Ω. Biến trở MN có điện trở 35 Ω. Câu a: tìm điện trở đoạn MC để đèn sáng bình thường. Câu b: con chạy ở đâu thì ampe kế chỉ nhỏ nhất? Câu c: thay ampe kế bằng đèn 6 V – 12 W, thay đèn cũ bằng điện trở 6 Ω, biến trở có điện trở toàn phần R chưa biết. Tìm R nhỏ nhất để đèn mới sáng bình thường được.",
  "a) MC = 6√6 ≈ 14,7 Ω; b) MC = 18 Ω (MC/MN = 18/35); c) R nhỏ nhất 8 Ω",
  ["Đặt MC = x. Cụm song song có điện trở 6x/(x + 6), phần còn lại 36 − x.", "Câu b: I_A = 216/(540 − (x − 18)²)."],
  "a) Đèn cần 6 V nên phần còn lại nhận 30 V: 6x/(x + 6) : (36 − x) = 6 : 30, suy ra x² = 216, x ≈ 14,7 Ω. b) I_A = 216/(540 − (x − 18)²), nhỏ nhất khi x = 18 Ω. c) Điều kiện đèn sáng bình thường dẫn tới −x² + (R − 2)x + 9R − 81 = 0. Có nghiệm khi R² + 32R − 320 ≥ 0, tức R ≥ 8 Ω.",
  "abs(6*sqrt(216)/(sqrt(216)+6)/(36-sqrt(216))-0.2)<1e-9 and 8**2+32*8-320==0")
P("D29", 3, "Hải Dương 2016 – Ảnh của điểm sáng ngoài trục",
  "Đề thi vào 10 chuyên Nguyễn Trãi Hải Dương năm 2016. Điểm sáng S cách trục chính 5 cm, cho ảnh S' ở phía bên kia trục chính. Chân đường vuông góc từ S xuống trục là H, từ S' là K. Biết H cách tiêu điểm gần nó 10 cm (H nằm ngoài tiêu cự), và K cách tiêu điểm phía bên kia 40 cm. Câu 1: tính tiêu cự. Câu 2: giữ thấu kính cố định, dịch S song song với trục chính, ra xa thấu kính với tốc độ 15 cm/s. Tính tốc độ trung bình của ảnh trong 1 giây đầu.",
  "1) f = 20 cm; 2) khoảng 24,7 cm/s (6√17 cm/s)",
  ["Ảnh ở khác phía trục chính nên là ảnh thật, thấu kính hội tụ: d = f + 10, d' = f + 40.", "Câu 2: sau 1 s, d = 45 cm. Tính vị trí và độ cao ảnh mới rồi lấy độ dài đoạn nối hai vị trí ảnh."],
  "1) 1/f = 1/(f + 10) + 1/(f + 40), suy ra f² = 400, f = 20 cm, d = 30, d' = 60, ảnh cách trục 10 cm. 2) Sau 1 s: d = 45 cm, d' = 36 cm, ảnh cách trục 5·36/45 = 4 cm. Ảnh dịch 24 cm dọc trục và 6 cm theo phương vuông góc: quãng đường √(24² + 6²) = 6√17 ≈ 24,7 cm, tốc độ trung bình khoảng 24,7 cm/s.",
  "abs(1/30+1/60-1/20)<1e-12 and abs(1/(1/20-1/45)-36)<1e-9 and abs(hypot(24,6)-24.74)<0.01")
P("D30", 2, "Quảng Bình 2013 – Tàu hỏa, xe máy, xe đạp",
  "Đề thi vào 10 chuyên Quảng Bình năm 2013. Một tàu hỏa dài 150 m chạy với tốc độ 10 m/s. Trên đường song song, một xe máy và một xe đạp chạy ngược chiều nhau. Lúc t bằng 0, xe máy bắt đầu đuổi kịp đuôi tàu, còn xe đạp vừa gặp đầu tàu. Câu a: xe máy vượt qua đầu tàu sau khi đi được 400 m. Tính tốc độ xe máy. Câu b: xe máy và xe đạp gặp nhau tại chỗ cách đầu tàu 105 m. Tính tốc độ xe đạp.",
  "a) 16 m/s; b) 4 m/s",
  ["Câu a: trong cùng thời gian, xe máy đi 400 m, tàu đi 400 − 150 = 250 m.", "Câu b: lúc t bằng 0 hai xe cách nhau 150 m và đi lại gần nhau."],
  "a) 400/v1 = 250/10, nên v1 = 16 m/s. b) Thời gian gặp nhau t = 150/(16 + v2). Khoảng cách đến đầu tàu: (10 + v2)·t = 105. Giải ra v2 = 4 m/s, t = 7,5 s.",
  "400/(250/10)==16 and abs((10+4)*150/(16+4)-105)<1e-9")
P("D31", 3, "Quảng Bình 2013 – Rót nước sôi vào hốc băng",
  "Đề thi vào 10 chuyên Quảng Bình năm 2013. Trong một khối nước đá rất lớn ở 0 độ C có một cái hốc thể tích 1000 cm³. Rót từ từ nước 100 độ C vào hốc. Khối lượng riêng nước 1000, nước đá 900 kg/m³, nhiệt dung riêng nước 4200, nhiệt nóng chảy nước đá 336 000 J/kg. Câu a: rót 0,1 kg nước. Tính khối lượng nước trong hốc khi cân bằng. Câu b: tính khối lượng nước lớn nhất rót được vào hốc.",
  "a) 0,225 kg; b) khoảng 1,16 kg (36/31 kg)",
  ["Nước nóng hạ xuống 0 độ làm tan một lượng đá: m_tan = m·4200·100/336 000 = 1,25m.", "Câu b: đá tan làm hốc rộng thêm, nhưng nước tan ra chiếm ít thể tích hơn đá. Hốc đầy khi thể tích nước bằng thể tích hốc mới."],
  "a) Đá tan 1,25·0,1 = 0,125 kg, nước trong hốc 0,225 kg, chiếm 225 cm³ < 1000 cm³. b) Rót M thì nước trong hốc 2,25M, hốc rộng thêm 1,25M/D_đá. Điều kiện: 2,25M/1000 = 0,001 + 1,25M/900, nên M = 36/31 ≈ 1,16 kg.",
  "abs(0.1*4200*100/336000-0.125)<1e-9 and abs(0.001/(2.25/1000-1.25/900)-36/31)<1e-9")
P("D32", 3, "Quảng Bình 2013 – Chùm sáng hội tụ qua lỗ tròn",
  "Đề thi vào 10 chuyên Quảng Bình năm 2013. Chiếu một chùm sáng hội tụ hình nón qua một lỗ tròn bán kính 2,5 cm trên màn M1. Trên màn M2 song song, cách M1 20 cm, thu được hình tròn sáng bán kính 2 cm, đồng tâm với lỗ. Lắp khít một thấu kính hội tụ vào lỗ thì trên M2 thu được một điểm sáng. Tính tiêu cự thấu kính.",
  "25 cm",
  ["Chưa có thấu kính, chùm hội tụ tại điểm S sau M1. Dùng tam giác đồng dạng: 2,5/OS = 2/(OS − 20).", "Với thấu kính, S là vật ảo, ảnh rơi đúng trên M2."],
  "Tam giác đồng dạng: OS = 100 cm. Thấu kính biến chùm hội tụ về S thành chùm hội tụ tại M2, cách 20 cm. Từ hình học: f/(f − 20) = 100/20, nên f = 25 cm. Kiểm tra bằng công thức với vật ảo: 1/f = 1/20 − 1/100 = 1/25.",
  "abs(1/(1/20-1/100)-25)<1e-9 and abs(2.5*80/100-2)<1e-9")
P("D33", 3, "Quảng Bình 2013 – Biến trở có ampe kế",
  "Đề thi vào 10 chuyên Quảng Bình năm 2013. Mạch gồm: điện trở r bằng 20 Ω, nối tiếp đoạn CN của biến trở MN (điện trở toàn phần 60 Ω, C là con chạy), nối tiếp một cụm gồm hai nhánh song song: nhánh thứ nhất là đoạn MC nối tiếp ampe kế lí tưởng, nhánh thứ hai là điện trở R bằng 15 Ω. Hiệu điện thế U không đổi. Câu a: con chạy ở chính giữa thì ampe kế chỉ 0,1 A. Tính U. Câu b: con chạy ở đâu thì ampe kế chỉ nhỏ nhất?",
  "a) 18 V; b) khi điện trở đoạn MC bằng 40 Ω (ampe kế chỉ khoảng 0,096 A)",
  ["Đặt MC = x. Ampe kế đo dòng qua đoạn MC. Hiệu điện thế cụm song song chia cho x là số chỉ ampe kế.", "Biến đổi được I_A = U·R / (−x² + 80x + 1200). Mẫu số là tam thức bậc hai, lớn nhất tại x = 40."],
  "a) x = 30 Ω: hiệu điện thế cụm song song = 0,1·30 = 3 V, dòng qua R = 3/15 = 0,2 A, dòng mạch chính 0,3 A. Điện trở toàn mạch 20 + 30 + 10 = 60 Ω, nên U = 0,3·60 = 18 V. b) Với MC = x: I_A = U·R/[(80 − x)(x + 15) + 15x] = 270/(−x² + 80x + 1200). Mẫu số lớn nhất khi x = 40 Ω, lúc đó I_A = 270/2800 ≈ 0,096 A, nhỏ nhất.",
  "abs(270/(-900+2400+1200)-0.1)<1e-9 and abs(0.3*60-18)<1e-9")

